	runes := make([]rune, 0, len(s))
	for _, r := range s {
		runes = append(runes, r)
	}

	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}

	return string(runes)
}
```

Both approaches are equivalent; the first (`[]rune(s)`) is more idiomatic Go.

