## Reading and Unmarshaling a JSON Config File in Go

### Config Structure and Implementation

```go
package main

import (
	"encoding/json"
	"fmt"
	"os"
)

// Config holds the application configuration.
type Config struct {
	Name string `json:"name"`
	Port int    `json:"port"`
}

// LoadConfig reads a JSON file from the given path and unmarshals it into a Config struct.
func LoadConfig(path string) (*Config, error) {
	// Read the entire file into memory.
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("reading config file %q: %w", path, err)
	}

	// Unmarshal the JSON data into the Config struct.
	var cfg Config
	if err := json.Unmarshal(data, &cfg); err != nil {
		return nil, fmt.Errorf("parsing config file %q: %w", path, err)
	}

	// Validate required fields.
	if cfg.Name == "" {
		return nil, fmt.Errorf("config validation: 'name' field is required")
	}
	if cfg.Port <= 0 || cfg.Port > 65535 {
		return nil, fmt.Errorf("config validation: 'port' must be between 1 and 65535, got %d", cfg.Port)
	}

	return &cfg, nil
}

func main() {
	cfg, err := LoadConfig("config.json")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Loaded config — Name: %s, Port: %d\n", cfg.Name, cfg.Port)
}
```

### Example `config.json`

```json
{
  "name": "my-service",
  "port": 8080
}
```

### Unit Tests

```go
package main

import (
	"os"
	"path/filepath"
	"testing"
)

// writeTemp creates a temporary JSON file with the given content and returns its path.
func writeTemp(t *testing.T, content string) string {
	t.Helper()
	tmp := filepath.Join(t.TempDir(), "config.json")
	if err := os.WriteFile(tmp, []byte(content), 0600); err != nil {
		t.Fatalf("failed to write temp file: %v", err)
	}
	return tmp
}

func TestLoadConfig_Success(t *testing.T) {
	path := writeTemp(t, `{"name":"my-service","port":8080}`)

	cfg, err := LoadConfig(path)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Name != "my-service" {
		t.Errorf("expected Name %q, got %q", "my-service", cfg.Name)
	}
	if cfg.Port != 8080 {
		t.Errorf("expected Port %d, got %d", 8080, cfg.Port)
	}
}

func TestLoadConfig_FileNotFound(t *testing.T) {
	_, err := LoadConfig("nonexistent.json")
	if err == nil {
		t.Fatal("expected an error for missing file, got nil")
	}
}

func TestLoadConfig_InvalidJSON(t *testing.T) {
	path := writeTemp(t, `{invalid json}`)

	_, err := LoadConfig(path)
	if err == nil {
		t.Fatal("expected a parse error, got nil")
	}
}

func TestLoadConfig_MissingName(t *testing.T) {
	path := writeTemp(t, `{"port":8080}`)

	_, err := LoadConfig(path)
	if err == nil {
		t.Fatal("expected a validation error for missing name, got nil")
	}
}

func TestLoadConfig_InvalidPort(t *testing.T) {
	cases := []struct {
		label   string
		content string
	}{
		{"zero port", `{"name":"svc","port":0}`},
		{"negative port", `{"name":"svc","port":-1}`},
		{"port too high", `{"name":"svc","port":99999}`},
	}

	for _, tc := range cases {
		t.Run(tc.label, func(t *testing.T) {
			path := writeTemp(t, tc.content)
			_, err := LoadConfig(path)
			if err == nil {
				t.Fatalf("expected validation error for %s, got nil", tc.label)
			}
		})
	}
}
```

### Key Points

| Aspect | Detail |
|---|---|
| **File reading** | `os.ReadFile` reads the whole file in one call (Go 1.16+) |
| **Error wrapping** | `%w` preserves the original error for `errors.Is` / `errors.As` |
| **Validation** | Checked after unmarshaling so callers get clear domain errors |
| **JSON tags** | `json:"name"` maps lowercase JSON keys to exported struct fields |
| **Tests** | Use `t.TempDir()` for automatic cleanup of temporary files |

## Reading and Unmarshaling a JSON Config File in Go

### Config Structure and Implementation

```go
package main

import (
	"encoding/json"
	"fmt"
	"os"
)

// Config holds the application configuration.
type Config struct {
	Name string `json:"name"`
	Port int    `json:"port"`
}

// LoadConfig reads a JSON file from the given path and unmarshals it into a Config struct.
func LoadConfig(path string) (*Config, error) {
	// Validate that a path was provided
	if path == "" {
		return nil, fmt.Errorf("config file path must not be empty")
	}

	// Read the entire file into memory
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("failed to read config file %q: %w", path, err)
	}

	// Unmarshal the JSON data into the Config struct
	var cfg Config
	if err := json.Unmarshal(data, &cfg); err != nil {
		return nil, fmt.Errorf("failed to parse config file %q: %w", path, err)
	}

	// Validate required fields
	if cfg.Name == "" {
		return nil, fmt.Errorf("config field 'name' must not be empty")
	}
	if cfg.Port <= 0 || cfg.Port > 65535 {
		return nil, fmt.Errorf("config field 'port' must be between 1 and 65535, got %d", cfg.Port)
	}

	return &cfg, nil
}

func main() {
	cfg, err := LoadConfig("config.json")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error loading config: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Loaded config — Name: %s, Port: %d\n", cfg.Name, cfg.Port)
}
```

### Example `config.json`

```json
{
  "name": "my-service",
  "port": 8080
}
```

