### Config Structure and Implementation

```go
package main

import (
	"encoding/json"
	"fmt"
	"os"
)

// Config holds the application configuration.
type Config struct {
	Name string `json:"name"`
	Port int    `json:"port"`
}

// LoadConfig reads a JSON file from the given path and unmarshals it into a Config struct.
func LoadConfig(path string) (*Config, error) {
	// Open the file
	file, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("opening config file %q: %w", path, err)
	}
	defer file.Close()

	// Decode JSON directly from the file reader
	var cfg Config
	decoder := json.NewDecoder(file)
	decoder.DisallowUnknownFields() // Catch unexpected fields in the JSON

	if err := decoder.Decode(&cfg); err != nil {
		return nil, fmt.Errorf("decoding config file %q: %w", path, err)
	}

	// Validate required fields
	if err := cfg.validate(); err != nil {
		return nil, fmt.Errorf("invalid config: %w", err)
	}

	return &cfg, nil
}

// validate checks that required Config fields are present and valid.
func (c *Config) validate() error {
	if c.Name == "" {
		return fmt.Errorf("name is required and cannot be empty")
	}
	if c.Port <= 0 || c.Port > 65535 {
		return fmt.Errorf("port must be between 1 and 65535, got %d", c.Port)
	}
	return nil
}

func main() {
	cfg, err := LoadConfig("config.json")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Loaded config:\n  Name: %s\n  Port: %d\n", cfg.Name, cfg.Port)
}
