func LoadConfig(filePath string) (*Config, error) {
	// Open the file
	file, err := os.Open(filePath)
	if err != nil {
		return nil, fmt.Errorf("failed to open config file %q: %w", filePath, err)
	}
	defer file.Close()

	// Decode JSON directly from the file reader
	var cfg Config
	decoder := json.NewDecoder(file)
	decoder.DisallowUnknownFields() // Reject unexpected fields

	if err := decoder.Decode(&cfg); err != nil {
		return nil, fmt.Errorf("failed to decode config file %q: %w", filePath, err)
	}

	// Validate required fields
	if err := cfg.validate(); err != nil {
		return nil, fmt.Errorf("invalid config: %w", err)
	}

	return &cfg, nil
}

// validate checks that required Config fields are set.
func (c *Config) validate() error {
	if c.Name == "" {
		return fmt.Errorf("name is required and cannot be empty")
	}
	if c.Port <= 0 || c.Port > 65535 {
		return fmt.Errorf("port must be between 1 and 65535, got %d", c.Port)
	}
	return nil
}

func main() {
	cfg, err := LoadConfig("config.json")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error loading config: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Loaded config: Name=%q, Port=%d\n", cfg.Name, cfg.Port)
}
