)

func TestLoadConfig(t *testing.T) {
	t.Run("valid config", func(t *testing.T) {
		// Write a temporary config file.
		content := `{"name": "test-service", "port": 9090}`
		tmpFile := writeTempFile(t, content)

		cfg, err := LoadConfig(tmpFile)
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if cfg.Name != "test-service" {
			t.Errorf("expected name %q, got %q", "test-service", cfg.Name)
		}
		if cfg.Port != 9090 {
			t.Errorf("expected port %d, got %d", 9090, cfg.Port)
		}
	})

	t.Run("file not found", func(t *testing.T) {
		_, err := LoadConfig("nonexistent.json")
		if err == nil {
			t.Fatal("expected an error, got nil")
		}
	})

	t.Run("invalid JSON", func(t *testing.T) {
		tmpFile := writeTempFile(t, `{invalid json}`)

		_, err := LoadConfig(tmpFile)
		if err == nil {
			t.Fatal("expected a parse error, got nil")
		}
	})

	t.Run("missing name field", func(t *testing.T) {
		tmpFile := writeTempFile(t, `{"port": 8080}`)

		_, err := LoadConfig(tmpFile)
		if err == nil {
			t.Fatal("expected a validation error, got nil")
		}
	})

	t.Run("missing port field", func(t *testing.T) {
		tmpFile := writeTempFile(t, `{"name": "my-service"}`)

		_, err := LoadConfig(tmpFile)
		if err == nil {
			t.Fatal("expected a validation error, got nil")
		}
	})
}

// writeTempFile creates a temporary file with the given content and returns its path.
func writeTempFile(t *testing.T, content string) string {
	t.Helper()

	f, err := os.CreateTemp("", "config-*.json")
	if err != nil {
		t.Fatalf("creating temp file: %v", err)
	}
	t.Cleanup(func() { os.Remove(f.Name()) })

	if _, err := f.WriteString(content); err != nil {
		t.Fatalf("writing temp file: %v", err)
	}
	f.Close()

	return f.Name()
}
