package main

import (
	"fmt"
	"sync"
	"time"
)

// Worker processes jobs from the jobs channel
func worker(id int, jobs <-chan int, results chan<- int, wg *sync.WaitGroup) {
	defer wg.Done()
	for job := range jobs {
		fmt.Printf("Worker %d processing job %d\n", id, job)
		result := processJob(job)
		results <- result
	}
	fmt.Printf("Worker %d finished\n", id)
}

// processJob simulates work being done on a job
func processJob(job int) int {
	time.Sleep(100 * time.Millisecond) // Simulate work
	return job * job                   // Return job squared as result
}

// WorkerPool spawns n goroutines to process jobs concurrently
func WorkerPool(jobs <-chan int, n int) <-chan int {
	results := make(chan int, n)
	var wg sync.WaitGroup

	// Spawn n workers
	for i := 1; i <= n; i++ {
		wg.Add(1)
		go worker(i, jobs, results, &wg)
	}

	// Close results channel when all workers are done
	go func() {
		wg.Wait()
		close(results)
	}()

	return results
}

func main() {
	const numJobs = 10
	const numWorkers = 3

	// Create and populate jobs channel
	jobs := make(chan int, numJobs)
	for i := 1; i <= numJobs; i++ {
		jobs <- i
	}
	close(jobs) // Close after sending all jobs

	fmt.Printf("Starting worker pool with %d workers for %d jobs\n\n", numWorkers, numJobs)
	start := time.Now()

	// Start worker pool and collect results
	results := WorkerPool(jobs, numWorkers)

	// Collect all results
	var allResults []int
	for result := range results {
		allResults = append(allResults, result)
	}

	elapsed := time.Since(start)
