### Enhanced Version with Context & Error Handling

```go
package main

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

// Result holds the job result or error
type Result struct {
	JobID  int
	Value  int
	Error  error
}

// WorkerPoolWithContext spawns n workers with context cancellation support
func WorkerPoolWithContext(ctx context.Context, jobs <-chan int, n int) <-chan Result {
	results := make(chan Result, n)
	var wg sync.WaitGroup

	for i := 1; i <= n; i++ {
		wg.Add(1)
		go func(workerID int) {
			defer wg.Done()
			for {
				select {
				case <-ctx.Done():
					fmt.Printf("Worker %d cancelled\n", workerID)
					return
				case job, ok := <-jobs:
					if !ok {
						return // Channel closed, no more jobs
					}
					result, err := processJobWithError(job)
					results <- Result{
						JobID: job,
						Value: result,
						Error: err,
					}
				}
			}
		}(i)
	}

	go func() {
		wg.Wait()
		close(results)
	}()

	return results
}

func processJobWithError(job int) (int, error) {
	time.Sleep(50 * time.Millisecond)
	if job%5 == 0 {
		return 0, errors.New("job divisible by 5 failed")
	}
	return job * job, nil
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	const numJobs = 10
	jobs := make(chan int, numJobs)
	for i := 1; i <= numJobs; i++ {
		jobs <- i
	}
	close(jobs)

	results := WorkerPoolWithContext(ctx, jobs, 3)

	for result := range results {
		if result.Error != nil {
			fmt.Printf("Job %d failed: %v\n", result.JobID, result.Error)
		} else {
			fmt.Printf("Job %d succeeded: %d\n", result.JobID, result.Value)
		}
	}
}
```

### Key Concepts

| Concept | Description |
|---------|-------------|
| **Buffered channels** | Prevent goroutine blocking when sending results |
| **`sync.WaitGroup`** | Tracks when all workers complete |
| **`range` over channel** | Workers automatically stop when jobs channel closes |
| **Goroutine cleanup** | Results channel closed after all workers finish |
| **Context cancellation** | Graceful shutdown via `ctx.Done()` |

### Design Decisions

- **`jobs <-chan int`** — receive-only channel prevents workers from sending to jobs
- **`results chan<- int`** — send-only channel prevents workers from reading results
- **Buffered results channel** — avoids blocking workers while results are collected
- **WaitGroup + goroutine** — cleanly closes results channel after all workers finish

