	var wg sync.WaitGroup

	// Spawn n workers
	for i := 1; i <= n; i++ {
		wg.Add(1)
		go func(workerID int) {
			defer wg.Done()
			for {
				select {
				case <-ctx.Done():
					fmt.Printf("Worker %d: context cancelled\n", workerID)
					return
				case job, ok := <-jobs:
					if !ok {
						return // Channel closed, no more jobs
					}

					result := processJob(workerID, job)
					select {
					case results <- result:
					case <-ctx.Done():
						return
					}
				}
			}
		}(i)
	}

	// Close results when all workers finish
	go func() {
		wg.Wait()
		close(results)
	}()

	// Collect all results
	var allResults []ProcessResult
	for result := range results {
		allResults = append(allResults, result)
	}

	return allResults
}

// processJob simulates job processing with potential errors
func processJob(workerID, job int) ProcessResult {
	time.Sleep(5 * time.Millisecond)

	// Simulate occasional errors
	if job%7 == 0 {
		return ProcessResult{
			JobID:  job,
			Err:    errors.New("job failed: divisible by 7"),
			Worker: workerID,
		}
	}

	return ProcessResult{
		JobID:  job,
		Value:  job * job,
		Worker: workerID,
	}
}

func main() {
	const numJobs = 20
	const numWorkers = 4

	// Create context with timeout
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	// Create and populate jobs channel
	jobs := make(chan int, numJobs)
	for i := 1; i <= numJobs; i++ {
		jobs <- i
	}
	close(jobs)

	fmt.Printf("Processing %d jobs with %d workers\n\n", numJobs, numWorkers)

	results := WorkerPoolWithContext(ctx, jobs, numWorkers)

	// Display results
	successCount, errorCount := 0, 0
	for _, r := range results {
		if r.Err != nil {
			fmt.Printf("❌ Job %d failed (Worker %d): %v\n", r.JobID, r.Worker, r.Err)
			errorCount++
		} else {
			fmt.Printf("✅ Job %d → %d (Worker %d)\n", r.JobID, r.Value, r.Worker)
			successCount++
		}
	}

	fmt.Printf("\nSummary: %d succeeded, %d failed\n", successCount, errorCount)
}
