// WorkerPool spawns n goroutines to process jobs concurrently
func WorkerPool(jobs <-chan int, n int) {
	if n <= 0 {
		fmt.Println("Worker pool requires at least 1 worker")
		return
	}

	jobChan := make(chan Job, n)    // Buffered channel for structured jobs
	results := make(chan Result, n) // Buffered channel for results
	var wg sync.WaitGroup

