// WorkerPoolWithContext adds cancellation support
func WorkerPoolWithContext(ctx context.Context, jobs <-chan int, n int) error {
	var wg sync.WaitGroup
	results := make(chan int, n)
	errChan := make(chan error, 1)

	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(workerID int) {
			defer wg.Done()
			for {
				select {
				case <-ctx.Done():
					fmt.Printf("Worker %d: context cancelled\n", workerID)
					return
				case job, ok := <-jobs:
					if !ok {
						return // Channel closed
					}
					select {
					case results <- job * job:
					case <-ctx.Done():
						return
					}
				}
			}
		}(i)
	}

	go func() {
		wg.Wait()
		close(results)
	}()

	for range results {
		// Process results
	}

	select {
	case err := <-errChan:
		return err
	default:
		return nil
	}
}
