## Worker Pool Implementation in Go

### Overview
A worker pool pattern manages a fixed number of goroutines that process jobs from a shared channel, providing controlled concurrency and efficient resource utilization.

### Implementation

```go
package main

import (
	"fmt"
	"sync"
	"time"
)

// Job represents a unit of work
type Job struct {
	ID      int
	Payload int
}

// Result represents the outcome of processing a job
type Result struct {
	JobID  int
	Output int
	Error  error
}

// worker processes jobs from the jobs channel and sends results to the results channel
func worker(id int, jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
	defer wg.Done()

	for job := range jobs {
		fmt.Printf("Worker %d processing job %d (payload: %d)\n", id, job.ID, job.Payload)

		// Simulate work
		time.Sleep(time.Duration(job.Payload) * time.Millisecond)
		output := job.Payload * job.Payload

		results <- Result{
			JobID:  job.ID,
			Output: output,
		}

		fmt.Printf("Worker %d completed job %d (result: %d)\n", id, job.ID, output)
	}
}

// WorkerPool spawns n goroutines to process jobs concurrently
func WorkerPool(jobs <-chan int, n int) {
	if n <= 0 {
		fmt.Println("Number of workers must be positive")
		return
	}

	var wg sync.WaitGroup
	results := make(chan Result, n) // Buffered channel to prevent blocking

	// Convert int channel to Job channel and spawn workers
	jobChan := make(chan Job, n)

	// Feed jobs into the job channel
	go func() {
		defer close(jobChan)
		jobID := 1
		for payload := range jobs {
			jobChan <- Job{ID: jobID, Payload: payload}
			jobID++
		}
	}()

	// Spawn n workers
	for i := 1; i <= n; i++ {
		wg.Add(1)
		go worker(i, jobChan, results, &wg)
	}

	// Close results channel when all workers are done
	go func() {
		wg.Wait()
		close(results)
	}()

	// Collect and display results
	for result := range results {
		if result.Error != nil {
			fmt.Printf("Job %d failed: %v\n", result.JobID, result.Error)
		} else {
			fmt.Printf("Job %d result: %d\n", result.JobID, result.Output)
		}
	}
}

// WorkerPoolSimple is a simpler version matching the exact function signature
func WorkerPoolSimple(jobs <-chan int, n int) {
	var wg sync.WaitGroup

	// Spawn exactly n workers
	for i := 1; i <= n; i++ {
		wg.Add(1)
		go func(workerID int) {
			defer wg.Done()
			for job := range jobs {
				fmt.Printf("Worker %d processing job: %d\n", workerID, job)
				// Simulate processing time
				time.Sleep(time.Duration(job) * time.Millisecond)
				fmt.Printf("Worker %d completed job: %d\n", workerID, job)
			}
		}(i)
	}

	wg.Wait()
	fmt.Println("All workers completed")
}

func main() {
