	const numWorkers = 3

	jobs := make(chan int, numJobs)

	// Send jobs and close the channel
	for i := 1; i <= numJobs; i++ {
		jobs <- i
	}
	close(jobs)

	workerpool.WorkerPool(jobs, numWorkers)

	// ── WorkerPool with Results ───────────────────────────────────
	fmt.Println("\n=== Worker Pool with Results ===")

	jobCh := make(chan workerpool.Job, numJobs)

	for i := 1; i <= numJobs; i++ {
		jobCh <- workerpool.Job{ID: i, Payload: i * 2}
	}
	close(jobCh)

	results := workerpool.WorkerPoolWithResults(jobCh, numWorkers)

	for result := range results {
		if result.Error != nil {
			fmt.Printf("Job %d failed: %v\n", result.JobID, result.Error)
			continue
		}
		fmt.Printf("Job %d → output: %d\n", result.JobID, result.Output)
