func WorkerPool(jobs <-chan int, n int) {
	var wg sync.WaitGroup

	worker := func(id int, jobs <-chan int) {
		defer wg.Done()
		for job := range jobs {
			// Process the job
			fmt.Printf("worker %d processed job %d\n", id, job)
		}
	}

	wg.Add(n)
	for i := 0; i < n; i++ {
		go worker(i, jobs)
	}

	wg.Wait()
}
