### The Code

```go
package main

import "fmt"

// Reverse returns its argument string reversed rune-wise.
// It correctly handles multi-byte UTF-8 characters.
func Reverse(s string) string {
	// Convert the string to a slice of runes. This is the key to handling
	// multi-byte characters correctly, as each "character" (code point)
	// becomes a single element in the slice.
	runes := []rune(s)

	// Use a classic two-pointer approach to swap runes in-place.
	// i starts at the beginning, j starts at the end.
	// They move towards the middle, swapping elements as they go.
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		// This is the idiomatic Go way to swap two variables.
		runes[i], runes[j] = runes[j], runes[i]
	}

	// Convert the modified rune slice back to a string.
	return string(runes)
}

func main() {
	// Example 1: Simple ASCII string
	input1 := "hello"
	reversed1 := Reverse(input1)
	fmt.Printf("Original:  '%s'\nReversed:  '%s'\n\n", input1, reversed1)

	// Example 2: String with multi-byte UTF-8 characters
	input2 := "Hello, 世界"
	reversed2 := Reverse(input2)
	fmt.Printf("Original:  '%s'\nReversed:  '%s'\n\n", input2, reversed2)

	// Example 3: String with emojis (which are also multi-byte)
	input3 := "Go is fun! 👍"
	reversed3 := Reverse(input3)
	fmt.Printf("Original:  '%s'\nReversed:  '%s'\n\n", input3, reversed3)

	// Example 4: A palindrome
	input4 := "madam"
	reversed4 := Reverse(input4)
	fmt.Printf("Original:  '%s'\nReversed:  '%s'\n\n", input4, reversed4)

	// Example 5: An empty string
	input5 := ""
	reversed5 := Reverse(input5)
	fmt.Printf("Original:  '%s'\nReversed:  '%s'\n\n", input5, reversed5)
}
```

### How to Run

