The most idiomatic and useful way to write this function is to use a `sync.WaitGroup` to allow the main program to wait for all the workers to finish their jobs.

### Recommended Idiomatic Solution (with `sync.WaitGroup`)

This version is more robust as it provides a mechanism for the caller to know when all the work is complete.

```go
package main

import (
	"fmt"
	"sync"
	"time"
)

// WorkerPool spawns n worker goroutines that will process jobs from the jobs channel.
// It uses a WaitGroup to signal when all workers have completed.
func WorkerPool(wg *sync.WaitGroup, jobs <-chan int, n int) {
	for i := 1; i <= n; i++ {
		// Add a count of 1 to the WaitGroup for each worker.
		wg.Add(1)

		// Spawn a worker goroutine.
		go worker(wg, i, jobs)
	}
}

// worker is the function that each goroutine will execute.
// It receives a unique id and the channel to read jobs from.
func worker(wg *sync.WaitGroup, id int, jobs <-chan int) {
	// Decrement the WaitGroup counter when the goroutine exits.
	defer wg.Done()

	fmt.Printf("Worker %d starting\n", id)

	// The for-range loop on a channel is a key pattern.
	// It will automatically block until a job is available
	// and will exit when the channel is closed by the sender.
	for j := range jobs {
		fmt.Printf("Worker %d started  job %d\n", id, j)
		// Simulate work by sleeping for a second.
		time.Sleep(time.Second)
		fmt.Printf("Worker %d finished job %d\n", id, j)
	}

	fmt.Printf("Worker %d shutting down\n", id)
}

func main() {
	const numJobs = 10
	const numWorkers = 3

	// Create a buffered channel to send jobs to the workers.
	jobs := make(chan int, numJobs)

	// A WaitGroup is used to wait for all goroutines to finish.
	var wg sync.WaitGroup

	// 1. Spawn the worker pool.
	// The workers will start immediately and block, waiting for jobs.
	fmt.Printf("Spawning %d workers...\n", numWorkers)
	WorkerPool(&wg, jobs, numWorkers)

	// 2. Send jobs to the workers.
	// This part of the code is the "producer".
	fmt.Printf("Sending %d jobs...\n", numJobs)
	for j := 1; j <= numJobs; j++ {
		jobs <- j
	}

	// 3. Close the jobs channel.
	// This is a critical step! It signals to the worker goroutines (in their
	// for-range loop) that no more jobs will be sent.
	close(jobs)
	fmt.Println("All jobs sent. Closing channel.")

	// 4. Wait for all the workers to finish.
	// This blocks the main goroutine until the WaitGroup counter is zero.
	// The counter becomes zero only after every worker has called wg.Done().
	wg.Wait()

	fmt.Println("All workers finished. Program complete.")
}
```

