	"time"
)

// worker is the function that each goroutine will run.
// It receives jobs from the jobs channel and signals it's done via the WaitGroup.
func worker(id int, jobs <-chan int, wg *sync.WaitGroup) {
	// Signal to the WaitGroup that this goroutine is done when the function returns.
	defer wg.Done()

	// This is the core of the worker. It ranges over the 'jobs' channel.
	// The loop will automatically break when the 'jobs' channel is closed
	// and there are no more items to receive.
	for j := range jobs {
		fmt.Printf("Worker %d started  job %d\n", id, j)
		// Simulate work by sleeping for a second.
		time.Sleep(time.Second)
		fmt.Printf("Worker %d finished job %d\n", id, j)
	}
	fmt.Printf("Worker %d shutting down.\n", id)
}

// WorkerPool spawns n worker goroutines to process jobs.
// It blocks until all jobs have been processed.
func WorkerPool(jobs <-chan int, n int) {
	// A WaitGroup waits for a collection of goroutines to finish.
	var wg sync.WaitGroup

	// Spawn 'n' worker goroutines.
	for w := 1; w <= n; w++ {
		// Increment the WaitGroup counter.
		wg.Add(1)
		// Launch a new goroutine to run the worker function.
		go worker(w, jobs, &wg)
	}

	// Wait for all the goroutines to call wg.Done().
	// This will block until the WaitGroup counter is zero.
	wg.Wait()
}

// main function to set up and run the example.
func main() {
	const numJobs = 10
	const numWorkers = 3

	// Create a channel to send jobs to the workers.
	// This channel is unbuffered, meaning a sender will block until a receiver is ready.
	jobs := make(chan int, numJobs)

	fmt.Printf("Starting a worker pool with %d workers and %d jobs.\n", numWorkers, numJobs)

	// --- Job Producer ---
	// In a separate goroutine, we'll send jobs to the 'jobs' channel.
	// This runs concurrently with the WorkerPool.
	go func() {
		for j := 1; j <= numJobs; j++ {
			fmt.Printf("Enqueuing job %d\n", j)
			jobs <- j
		}
		// After sending all jobs, we MUST close the channel.
		// This is the signal to the workers' 'for range' loops that no more jobs are coming.
		close(jobs)
		fmt.Println("All jobs enqueued and channel closed.")
	}()

	// --- Job Consumer ---
	// Start the worker pool. This call will block until all workers are finished.
	WorkerPool(jobs, numWorkers)

	fmt.Println("Worker pool finished. All jobs completed.")
}
