		// closure issue where all goroutines would share the same value of 'i'.
		go func(workerID int) {
			// Decrement the counter when the goroutine completes.
			defer wg.Done()

			// The worker continuously receives jobs from the 'jobs' channel.
			// The for...range loop on a channel will automatically break
			// when the channel is closed and all values have been received.
			for job := range jobs {
