				fmt.Printf("Worker %d finished job %d\n", workerID, job)
			}
			fmt.Printf("Worker %d shutting down.\n", workerID)
		}(i)
	}

	// Wait for all the worker goroutines to finish.
	// This call will block until the WaitGroup counter is zero.
	wg.Wait()
}

// main function to demonstrate the WorkerPool.
func main() {
	const numJobs = 10
	const numWorkers = 3

	// Create a buffered channel to send jobs to the workers.
	// A buffered channel allows us to send all jobs without waiting for a
	// worker to be immediately ready.
	jobs := make(chan int, numJobs)

	// --- Job Sending Stage ---
	fmt.Println("Sending jobs...")
	// Enqueue jobs.
	for j := 1; j <= numJobs; j++ {
		jobs <- j
	}
	// Close the channel to signal that no more jobs will be sent.
	// This is crucial for the workers' for...range loops to terminate.
	close(jobs)
	fmt.Println("All jobs sent.")

	// --- Worker Pool Stage ---
	fmt.Println("Starting worker pool.")
	// Start the worker pool. This will block until all work is done.
	WorkerPool(jobs, numWorkers)

	fmt.Println("All work completed.")
